import { mkdir, stat, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import { createHash } from "node:crypto";

const authQuery =
  /([?&](?:code|state|session_state|access_token|id_token)=)[^&\s"\\]+/gi;

export function redactor(secrets = []) {
  const originals = new Set();
  let values = [],
    literals = [];
  const addSecrets = (items) => {
    for (const item of items)
      if (typeof item === "string" && item.length) originals.add(item);
    values = [
      ...new Set(
        [...originals].flatMap((item) => [
          item,
          JSON.stringify(item).slice(1, -1),
        ]),
      ),
    ].sort((a, b) => b.length - a.length);
    // Preserve literal leftmost/longest matching without compiling caller
    // values into a regular expression with an engine-dependent size ceiling.
    literals = values.length
      ? [...new Set([...values, "[REDACTED]"])].sort(
          (a, b) => b.length - a.length,
        )
      : [];
  };
  addSecrets(secrets);
  const text = (value) => {
    // One replacement pass: inserted markers are never interpreted as secrets.
    const input = String(value);
    if (!literals.length) return input.replace(authQuery, "$1[REDACTED]");
    const parts = [];
    let offset = 0;
    while (offset < input.length) {
      let at = -1,
        length = 0;
      for (const literal of literals) {
        const found = input.indexOf(literal, offset);
        if (found !== -1 && (at === -1 || found < at)) {
          at = found;
          length = literal.length;
          if (at === offset) break;
        }
      }
      if (at === -1) {
        parts.push(input.slice(offset));
        break;
      }
      parts.push(input.slice(offset, at), "[REDACTED]");
      offset = at + length;
    }
    return parts.join("").replace(authQuery, "$1[REDACTED]");
  };
  const value = (input) => {
    if (typeof input === "string") {
      if (input.startsWith("data:image/"))
        return `[PRIVATE_IMAGE sha256=${createHash("sha256").update(input).digest("hex")}]`;
      return text(input);
    }
    if (Array.isArray(input)) return input.map(value);
    if (input && typeof input === "object")
      return Object.fromEntries(
        Object.entries(input).map(([key, item]) => [
          key,
          /^(authorization|api_key)$/i.test(key) ? "[REDACTED]" : value(item),
        ]),
      );
    return input;
  };
  return {
    text,
    value,
    addSecrets,
    hasSecret: (input) => {
      const text = String(input);
      return values.some((secret) => text.includes(secret));
    },
    get revision() {
      return originals.size;
    },
  };
}

export async function privateDirectory(path) {
  await mkdir(path, { recursive: true, mode: 0o700 });
  const info = await stat(path);
  if (
    !info.isDirectory() ||
    (info.mode & 0o077) !== 0 ||
    info.uid !== process.getuid()
  )
    throw new Error(
      "Artifact directory must be owned by this user and inaccessible to group/others",
    );
}

export async function privateFile(path, value) {
  await privateDirectory(dirname(path));
  await writeFile(
    path,
    typeof value === "string" || Buffer.isBuffer(value)
      ? value
      : JSON.stringify(value, null, 2),
    { mode: 0o600 },
  );
}

export const sha256 = (data) => createHash("sha256").update(data).digest("hex");

/** Supported AbortSignal reason distinguishes internal containment from Stop. */
export const interruption = (signal) =>
  signal?.reason?.code === "loki.runner.deadline/1"
    ? { actor: "harness", reason: "Time limit" }
    : signal?.reason?.code === "loki.runner.clarification-failure/1"
      ? {
          actor: "harness",
          reason: "Clarification IPC failure; effects unknown, do not replay",
        }
      : signal?.reason?.code === "loki.runner.worker-failure/1"
        ? {
            actor: "harness",
            reason:
              "Background worker rejection; effects unknown, do not replay",
          }
        : { actor: "operator", reason: "Operator Stop" };

// Keep compound input internals atomic. A failed settlement must not dispatch
// the remaining requested actions; completed dispatch receipts stay intact.
export async function executeSettledActions(actions, execute, settle) {
  for (const action of actions) {
    await execute(action);
    await settle();
  }
  if (!actions.length) await settle();
}

export async function settleComputerAction(wait, check) {
  check();
  let timer;
  try {
    // Reuse the guard's Stop/deadline/failure latch, including the final wait.
    await wait(
      new Promise((resolve) => {
        timer = setTimeout(resolve, 250);
      }),
    );
  } finally {
    clearTimeout(timer);
  }
  check();
}
